-- Venue Live Guest "Birthday Robot Factory". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara robotfactory), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'robotfactory', 'Birthday Robot Factory (pabrik robot)', 'robotfactory', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 128, 'center 38%',
  $t${"name":"Robot Factory","orn":"diamond","ui":{"ivory":"#F2F5FC","white":"#FFFFFF","soft":"#DCE6F8","soft2":"#9FB6E8","accent":"#2F5FD0","deep":"#17306E","ink":"#14264F","mute":"#5F7099","line":"#CBD8F0","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#F8FAFE","ink":"#14264F","accent":"#2F5FD0","gold":"#F5B700","leaf":"#DCE6F8","hbg":"rgba(242,245,252,.94)","hline":"#9FB6E8","motif":"diamond"},"hud":{"bg":"rgba(23,48,110,.88)","acc":"#FFC81F","on":"#14264F"},"scr":{"wine":"#17306E","veil":"242,245,252"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'robotfactory');
update public.live_venues set decor = $d${"speakers":{"url":"/assets/live-decor/robotfactory/speakers.webp","w":2.2},"balloons":{"url":"/assets/live-decor/robotfactory/balloons.webp","w":1.3,"x":3.3,"z":-18,"mirror":true},"stall_snacks":{"url":"/assets/live-decor/robotfactory/stall_snacks.webp","w":2.0},"stall_candy":{"url":"/assets/live-decor/robotfactory/stall_candy.webp","w":1.4},"stall_drinks":{"url":"/assets/live-decor/robotfactory/stall_drinks.webp","w":4.8},"photobooth":{"url":"/assets/live-decor/robotfactory/photobooth.webp","w":5.6},"claw":{"url":"/assets/live-decor/robotfactory/claw.webp","w":4.4},"arch":{"url":"/assets/live-decor/robotfactory/arch.webp"},"fountain":{"url":"/assets/live-decor/robotfactory/fountain.webp","w":5.8},"sign":{"url":"/assets/live-decor/robotfactory/sign.webp","w":1.5},"easel":{"url":"/assets/live-decor/robotfactory/easel.webp","w":2.8,"x":4.6,"z":8.2},"table":{"url":"/assets/live-decor/robotfactory/table.webp"},"banner":{"url":"/assets/live-decor/robotfactory/banner.webp","w":1.8},"gifts":{"url":"/assets/live-decor/robotfactory/gifts.webp","w":1.8},"lamp":{"url":"/assets/live-decor/robotfactory/lamp.webp","w":1.3,"x":3.3,"z":-12,"mirror":true},"rope":{"url":"/assets/live-decor/robotfactory/rope.webp","w":1.3,"x":3.3,"z":-6,"mirror":true},"planter":{"url":"/assets/live-decor/robotfactory/planter.webp","w":1.3,"x":3.3,"z":0,"mirror":true},"bush":{"url":"/assets/live-decor/robotfactory/bush.webp","w":1.3,"x":3.3,"z":6,"mirror":true},"av_host":{"url":"/assets/live-decor/robotfactory/av_host.webp","name":"Raka Teknisi"},"av_l1":{"url":"/assets/live-decor/robotfactory/av_l1.webp","name":"Kak Topi Kacamata"},"av_l2":{"url":"/assets/live-decor/robotfactory/av_l2.webp","name":"Kak Jubah Robot"},"av_l3":{"url":"/assets/live-decor/robotfactory/av_l3.webp","name":"Kak Insinyur"},"av_p1":{"url":"/assets/live-decor/robotfactory/av_p1.webp","name":"Kak Pita Kuning"},"av_p2":{"url":"/assets/live-decor/robotfactory/av_p2.webp","name":"Kak Hijab Biru"},"av_p3":{"url":"/assets/live-decor/robotfactory/av_p3.webp","name":"Kak Topi Robot"}}$d$::jsonb, background_url = '/assets/live-decor/robotfactory/painting.webp', active = true, updated_at = now() where key = 'robotfactory';
